<?php page_hero('Agenda', 'Kegiatan sekolah yang akan datang.', ['Informasi' => null, 'Agenda' => null], 'calendar'); ?>
<section class="section"><div class="container" style="max-width:900px"><?php if (!$rows): ?><p class="muted">Belum ada agenda mendatang.</p><?php endif; ?>
<?php foreach ($rows as $a): ?><article class="card reveal" style="flex-direction:row;margin-bottom:1rem"><div style="background:var(--primary);color:#fff;padding:1rem 1.3rem;text-align:center;min-width:92px"><b style="font-size:1.8rem;display:block;line-height:1"><?= e(date('d', strtotime($a['start_date']))) ?></b><span><?= e(fmt_date($a['start_date'], 'M Y')) ?></span></div><div class="card-body"><h3><?= e($a['title']) ?> <?= demo_badge($a) ?></h3><p><?= e($a['description']) ?></p><?php if ($a['location']): ?><div class="card-meta"><?= icon('map-pin', 14) ?> <?= e($a['location']) ?></div><?php endif; ?></div></article><?php endforeach; ?></div></section>
